<?php
namespace CmuLms;
final class CourseController {
 public function show():void{$u=Auth::require();$c=Course::find(Http::id('id'));if(!$c)exit('Course not found.');$tab=$_GET['tab']??'home';$data=['user'=>$u,'course'=>$c,'tab'=>$tab,'exams'=>Exam::forCourse($c['id']),'tasks'=>Task::forCourse($c['id']),'announcements'=>Announcement::forCourse($c['id']),'attendance'=>Attendance::forCourse($c['id']),'pools'=>QuestionPool::forCourse($c['id']),'students'=>Course::students($c['id']),'grades'=>Grade::forCourse($c['id'])];View::render('courses/show',$data);}
 public function post(\PDO $db):never{$u=Auth::role('teacher');View::checkCsrf();$course=(int)$_POST['course_id'];$type=$_POST['content_type']??'';if($type==='announcement'){$s=$db->prepare('INSERT INTO announcements(course_id,author_id,title,body,created_at,updated_at) VALUES(?,?,?,?,NOW(),NOW())');$s->execute([$course,$u['id'],trim($_POST['title']),trim($_POST['body'])]);}elseif($type==='task'){$s=$db->prepare('INSERT INTO tasks(course_id,title,type,description,due_at,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())');$s->execute([$course,trim($_POST['title']),'task',trim($_POST['body']),$_POST['due_at']?:null]);}elseif($type==='attendance'){$s=$db->prepare('INSERT INTO attendance_sessions(course_id,title,code_required,opens_at,closes_at,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())');$s->execute([$course,trim($_POST['title']),!empty($_POST['code_required']),$_POST['opens_at'],$_POST['closes_at']]);}$_SESSION['flash']='Content saved successfully.';Http::redirect('?route=course&id='.$course);}
}
